/* @autogenerated */
import { Component, input } from '@angular/core';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { TranslocoPipe } from '@jsverse/transloco';
import { IdentityPhase } from '@shared/context/identity/identity-provider.interface';

/** Fases que se enseñan como pasos: la de comprobar la sesión es la única hasta que se sabe si hay que entrar. */
const STEPS: IdentityPhase[] = ['signing-in', 'loading-user'];

/**
 * Pantalla de arranque a pantalla completa: ocupa el sitio del shell mientras la identidad no está resuelta, para que
 * no se vea un menú que luego desaparece o con el que aún no se puede hacer nada.
 */
@Component({
  selector: 'app-bootstrap',
  standalone: true,
  imports: [MatProgressSpinnerModule, TranslocoPipe],
  styleUrl: 'bootstrap.component.scss',
  template: `
    <div class="panel">
      @if (error()) {
        <div role="alert">
          <h1>{{ 'identity.errors.title' | transloco }}</h1>
          <p>{{ 'identity.errors.notConfigured' | transloco }}</p>
        </div>
      } @else {
        <mat-spinner diameter="40" aria-hidden="true" />
        <div role="status" aria-live="polite">
          <h1>{{ 'identity.bootstrap.' + phase() + '.title' | transloco }}</h1>
          <p>{{ 'identity.bootstrap.' + phase() + '.message' | transloco }}</p>
        </div>
        @if (phase() !== 'checking') {
          <ol class="steps" aria-hidden="true">
            @for (step of steps; track step) {
              <li [class.done]="isDone(step)" [class.current]="step === phase()"></li>
            }
          </ol>
        }
      }
    </div>
  `,
})
export class BootstrapComponent {
  readonly error = input(false);
  readonly phase = input<IdentityPhase>('checking');
  readonly steps = STEPS;

  isDone(step: IdentityPhase): boolean {
    return STEPS.indexOf(step) < STEPS.indexOf(this.phase());
  }
}
